"31.12. tarihli kapanış fişi: gelirler (sınıf 6) ve giderler (sınıf 5) 699/599 üzerinden 710'a, sonuç 720'ye, kurumlar vergisi 721/4810'a, net kâr ise 3410'a (zarar 3510'a) aktarılır. Sonraki yılın açılışı, 0–4 sınıflarının bakiyelerini 01.01. tarihli açılış bakiyesine taşır. Kapanıştan önce: tüm aylar deftere işlenmiş, sayım ve amortisman kaydedilmiş, PD beyannamesi kaydedilmiş olmalıdır (kesin vergiyi verir).",
